    function escapeHtml(value) {
      return String(value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
    }

    function HeroPanel() {
      return `
        <section class="hero-panel" aria-label="Support overview">
          <div>
            <span class="eyebrow">Support</span>
            <h1>Talk to our team when you need help moving forward.</h1>
            <p class="hero-copy">
              Share your details and a support specialist will get back to you with guidance,
              product answers, or next steps tailored to your request.
            </p>
          </div>
          <div class="hero-metrics" aria-hidden="true">
            <div class="metric">
              <strong>Fast</strong>
              <span>Clear follow-up from a real person.</span>
            </div>
            <div class="metric">
              <strong>Direct</strong>
              <span>Route your request to the right team.</span>
            </div>
            <div class="metric">
              <strong>Simple</strong>
              <span>Only the details we need to contact you.</span>
            </div>
          </div>
          <p class="support-note">We use your information only to respond to your support request.</p>
        </section>
      `;
    }

    function FormField(config) {
      const {
        id,
        label,
        type,
        name,
        placeholder,
        value,
        required,
        helperText,
        error,
        autocomplete
      } = config;

      const helperId = helperText ? `${id}-helper` : "";
      const errorId = `${id}-error`;
      const describedBy = [helperId, error ? errorId : ""].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <label for="${id}">${label}${required ? " *" : ""}</label>
          <input
            id="${id}"
            name="${name}"
            type="${type}"
            placeholder="${placeholder}"
            value="${escapeHtml(value)}"
            ${required ? "required" : ""}
            ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
            ${describedBy ? `aria-describedby="${describedBy}"` : ""}
            ${error ? 'aria-invalid="true"' : ""}
          />
          ${helperText ? `<p id="${helperId}" class="helper-text">${helperText}</p>` : ""}
          <p id="${errorId}" class="error-message" role="alert">${error ? error : ""}</p>
        </div>
      `;
    }

    function ContactForm() {
      return `
        <section class="form-panel">
          <div class="form-card">
            <h2>Contact support</h2>
            <p>
