      const nextErrors = {};
      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const phonePattern = /^[+]?[\d\s().-]{7,20}$/;

      if (!values.fullName.trim()) {
        nextErrors.fullName = "Please enter your full name.";
      }

      if (!values.email.trim()) {
        nextErrors.email = "Please enter your email address.";
      } else if (!emailPattern.test(values.email.trim())) {
        nextErrors.email = "Please enter a valid email address.";
      }

      if (values.phone.trim() && !phonePattern.test(values.phone.trim())) {
        nextErrors.phone = "Please use the phone format shown in the helper text.";
      }

      return nextErrors;
    }

    function render() {
      document.getElementById("app").innerHTML = App();
      bindEvents();
    }

    function bindEvents() {
      const form = document.getElementById("support-form");

      form.addEventListener("input", (event) => {
        const target = event.target;
        if (!(target instanceof HTMLInputElement)) {
          return;
        }

        state.values[target.name] = target.value;

        if (Object.keys(state.errors).length > 0) {
          state.errors = validate(state.values);
          state.isSubmitted = false;
          render();
        }
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        state.errors = validate(state.values);
        state.isSubmitted = Object.keys(state.errors).length === 0;
        render();
      });
    }

    render();
  </script>
</body>
