     function FormField(config) {
       const {
         id,
         label,
         type,
         name,
         placeholder,
         value,
         required,
         helperText,
         error,
         autocomplete
       } = config;

       const helperId = helperText ? `${id}-helper` : "";
       const errorId = `${id}-error`;
       const describedBy = [helperId, error ? errorId : ""].filter(Boolean).join(" ");

       return `
         <div class="form-field">
           <label for="${id}">${label}${required ? " *" : ""}</label>
