           <p id="${errorId}" class="error-message" role="alert">${error ? error : ""}</p>
         </div>
       `;
     }

     function ContactForm() {
       return `
         <section class="form-panel">
           <div class="form-card">
             <h2>Contact support</h2>
             <p>
               Fill out the form below and we&apos;ll reach out as soon as possible.
             </p>
             <form id="support-form" novalidate>
               ${FormField({
                 id: "full-name",
                 label: "Full name",
                 type: "text",
                 name: "fullName",
                 placeholder: "Jordan Lee",
                 value: state.values.fullName,
                 required: true,
                 helperText: "",
                 error: state.errors.fullName,
                 autocomplete: "name"
               })}
               ${FormField({
                 id: "email-address",
                 label: "Email address",
                 type: "email",
                 name: "email",
                 placeholder: "jordan@example.com",
                 value: state.values.email,
                 required: true,
                 helperText: "",
                 error: state.errors.email,
                 autocomplete: "email"
               })}
               ${FormField({
                 id: "phone-number",
                 label: "Phone number",
                 type: "tel",
                 name: "phone",
                 placeholder: "(555) 123-4567",
                 value: state.values.phone,
                 required: false,
                 helperText: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567.",
                 error: state.errors.phone,
                 autocomplete: "tel"
               })}
               <button class="submit-button" type="submit">Submit request</button>
               <p class="success-message" role="status">${state.isSubmitted ? "Thanks. Your support request is ready to send." : ""}</p>
             </form>
           </div>
         </section>
       `;
